// server.js - 回合制游戏专用WebSocket信令服务器
const WebSocket = require('ws');
const http = require('http');

// 1. 创建HTTP服务器（Render等平台需要HTTP服务器来挂载WebSocket）
const server = http.createServer((req, res) => {
    res.writeHead(200, { 'Content-Type': 'text/plain' });
        res.end('Game Signaling Server is Running.\n');
        });

        // 2. 创建WebSocket服务器，将其附加到HTTP服务器上
        const wss = new WebSocket.Server({ server });

        // 3. 用于存储所有已连接的客户端（玩家）
        const clients = new Set();

        // 4. 当有新的WebSocket连接建立时
        wss.on('connection', (ws) => {
            console.log('新的客户端已连接');
                // 将新客户端加入集合
                    clients.add(ws);

                        // 5. 监听客户端发来的消息
                            ws.on('message', (data) => {
                                    const message = data.toString();
                                            console.log('收到消息:', message);
                                                    
                                                            // 核心功能：将消息广播给所有【其他】客户端（实现状态同步）
                                                                    for (const client of clients) {
                                                                                // 确保连接是打开的，且不发送给自己
                                                                                            if (client !== ws && client.readyState === WebSocket.OPEN) {
                                                                                                            client.send(message);
                                                                                                                        }
                                                                                                                                }
                                                                                                                                    });

                                                                                                                                        // 6. 监听连接关闭
                                                                                                                                            ws.on('close', () => {
                                                                                                                                                    console.log('客户端已断开连接');
                                                                                                                                                            clients.delete(ws); // 从集合中移除
                                                                                                                                                                });

                                                                                                                                                                    // 7. 监听错误
                                                                                                                                                                        ws.on('error', (err) => {
                                                                                                                                                                                console.error('WebSocket发生错误:', err);
                                                                                                                                                                                        clients.delete(ws);
                                                                                                                                                                                            });
                                                                                                                                                                                            });

                                                                                                                                                                                            // 8. 启动服务器，监听Render动态分配的端口（必须使用 process.env.PORT）
                                                                                                                                                                                            const PORT = process.env.PORT || 3000;
                                                                                                                                                                                            server.listen(PORT, () => {
                                                                                                                                                                                                console.log(`信令服务器已启动，正在监听端口: ${PORT}`);
                                                                                                                                                                                                    console.log(`WebSocket服务地址: ws://localhost:${PORT}`);
                                                                                                                                                                                                    });